(function() {
  var _result = {};
  try {
    var comp = app.project.activeItem;
    if (!comp || !(comp instanceof CompItem)) {
      _result = {status:"error", message:"No active comp"};
      return JSON.stringify(_result);
    }
    var p = {compName: ${compName}, frameRate: ${frameRate}, intensity: ${intensity}};
    var tc = comp;
    if (p.compName) {
      for (var i = 1; i <= app.project.items.length; i++) {
        var it = app.project.items[i];
        if (it instanceof CompItem && it.name === p.compName) { tc = it; break; }
      }
    }
    var layer = tc.layer(1);
    if (!layer) { _result = {status:"error", message:"Layer not found"}; return JSON.stringify(_result); }
    var inten = p.intensity;
    // Phase1: Color Grading - warm brown-yellow tone
    var curves = layer.Effects.addProperty("ADBE Curves");
    curves.property("ADBE Curves Channel").setValue("RGB");
    var hue = layer.Effects.addProperty("ADBE Hue2");
    hue.property("ADBE Hue Hue").setValue(-10 * inten);
    var levels = layer.Effects.addProperty("ADBE Levels2");
    levels.property("Input Black").setValue(8);
    levels.property("Input White").setValue(235);
    levels.property("Gamma").setValue(1.1);
    // Phase2: Material Texture - wood grain
    var noise = layer.Effects.addProperty("ADBE Noise2");
    noise.property("ADBE Noise2 Amount").setValue(8 * inten);
    noise.property("ADBE Noise2 Use Color Noise").setValue(true);
    noise.property("ADBE Noise2 Seed").setValue(123);
    var vig = layer.Effects.addProperty("ADBE Vignette");
    vig.property("ADBE Vignette Amount").setValue(0.2 * inten);
    vig.property("ADBE Vignette Midpoint").setValue(0.75);
    // Phase3: Joint Seams - wooden pegs
    var jl = tc.layers.addShape();
    jl.name = "Wooden_Joints";
    var jp = [[0.5,0.28],[0.32,0.35],[0.68,0.35],[0.5,0.55],[0.4,0.58],[0.6,0.58],[0.38,0.72],[0.62,0.72]];
    var c = jl.property("Contents");
    for (var j = 0; j < jp.length; j++) {
      var g = c.addProperty("ADBE Vector Group");
      g.name = "Joint_" + j;
      var e = g.property("Contents").addProperty("ADBE Vector Shape - Ellipse");
      e.property("ADBE Ellipse Path Size").setValue([25, 20]);
      e.property("ADBE Ellipse Path Position").setValue([jp[j][0] * tc.width, jp[j][1] * tc.height]);
      var s = g.property("Contents").addProperty("ADBE Vector Graphic - Stroke");
      s.property("ADBE Stroke Color").setValue([0.15, 0.08, 0.02, 1]);
      s.property("ADBE Stroke Width").setValue(3);
      var f = g.property("Contents").addProperty("ADBE Vector Graphic - Fill");
      f.property("ADBE Fill Color").setValue([0.25, 0.15, 0.05, 1]);
    }
    // Phase4: Stop Motion - Time Remap expression
    var sfps = tc.frameRate;
    var tfps = p.frameRate;
    try {
      layer.timeRemapEnabled = true;
      layer.property("ADBE Time Remapping").expression = "frame = Math.floor(time * " + sfps + ") / " + sfps + "; stepped = Math.floor(frame * " + tfps + ") / " + tfps + "; stepped;";
    } catch(e3) {}
    var fl = tc.layers.addSolid([1, 1, 1], "StopMotion_Wooden", tc.width, tc.height, tc.frameRate);
    fl.adjustmentLayer = true;
    var bc = fl.Effects.addProperty("ADBE Brightness & Contrast");
    bc.property("ADBE Brightness-Contrast Brightness").expression = "random(-3, 3)";
    // Phase5: Miniature Scene - tilt-shift + vignette
    var ts = tc.layers.addSolid([1, 1, 1], "TiltShift_Wooden", tc.width, tc.height, tc.frameRate);
    ts.adjustmentLayer = true;
    var tv = ts.Effects.addProperty("ADBE Vignette");
    tv.property("ADBE Vignette Amount").setValue(0.25 * inten);
    tv.property("ADBE Vignette Midpoint").setValue(0.6);
    var tb = ts.Effects.addProperty("ADBE Gaussian Blur 2");
    tb.property("ADBE Gaussian Blur 2 Blurriness").setValue(3);
    _result = {status:"success", message:"wooden_puppet style applied", frameRate: p.frameRate, phases: 5};
  } catch(e) {
    _result = {status:"error", message:"Error: " + e.toString()};
  }
  return JSON.stringify(_result);
})();

